def _build_sa(s):
    n = len(s)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Initial ranks must respect lexicographic order of single symbols.
    vals = sorted(set(s))
    comp = {v: i for i, v in enumerate(vals)}
    rank = [comp[x] for x in s]

    sa = list(range(n))
    tmp = [0] * n
    k = 1
    shift = (n + 1).bit_length()

    while k < n:
        r = rank
        kk = k
        nn = n
        sh = shift

        # Pack (rank[i], rank[i+k]) into one integer key.
        # The out-of-range sentinel is 0; real ranks are stored as rank+1.
        keys = [
            ((r[i] + 1) << sh) | (r[i + kk] + 1 if i + kk < nn else 0)
            for i in range(nn)
        ]

        sa.sort(key=keys.__getitem__)

        tmp[sa[0]] = 0
        classes = 1
        prev_key = keys[sa[0]]

        for j in range(1, nn):
            idx = sa[j]
            key = keys[idx]
            if key != prev_key:
                classes += 1
                prev_key = key
            tmp[idx] = classes - 1

        rank, tmp = tmp, rank

        if classes == nn:
            break
        k <<= 1

    return sa


def _build_lcp(s, sa):
    n = len(s)
    if n <= 1:
        return []

    inv = [0] * n
    for i, p in enumerate(sa):
        inv[p] = i

    lcp = [0] * (n - 1)
    h = 0
    ss = s
    nn = n

    for i in range(nn):
        r = inv[i]
        if r == nn - 1:
            h = 0
            continue

        j = sa[r + 1]
        while i + h < nn and j + h < nn and ss[i + h] == ss[j + h]:
            h += 1

        lcp[r] = h
        if h:
            h -= 1

    return lcp


def longest_shared_run(traces: list[list[int]], k: int) -> tuple[int, list[int]]:
    t = len(traces)

    # k == 1: any trace substring qualifies, so take a longest whole trace.
    if k == 1:
        best_trace = None
        best_len = -1
        for tr in traces:
            l = len(tr)
            if best_trace is None or l > best_len or (l == best_len and tr < best_trace):
                best_trace = tr
                best_len = l

        if best_trace is None or best_len == 0:
            return (0, [])
        return (best_len, best_trace.copy())

    # Small mask popcount table; number of traces is tiny.
    pop = [0] * (1 << t)
    for i in range(1, 1 << t):
        pop[i] = pop[i >> 1] + (i & 1)

    # Quick necessary/sufficient check for length 1.
    nonempty = 0
    max_len = 0
    code_masks = {}

    for tid, tr in enumerate(traces):
        l = len(tr)
        if not l:
            continue
        nonempty += 1
        if l > max_len:
            max_len = l

        bit = 1 << tid
        for x in set(tr):
            code_masks[x] = code_masks.get(x, 0) | bit

    if nonempty < k or max_len == 0:
        return (0, [])

    has_len_one = False
    for m in code_masks.values():
        if pop[m] >= k:
            has_len_one = True
            break

    if not has_len_one:
        return (0, [])

    del code_masks

    # Build one concatenated integer sequence.
    # Each trace is terminated by a unique negative separator, smaller than all event codes.
    seq = []
    tid_at = []
    bit_at = []
    rem = []
    starts = []

    for tid, tr in enumerate(traces):
        starts.append(len(seq))
        bit = 1 << tid
        l = len(tr)

        for off, val in enumerate(tr):
            seq.append(val)
            tid_at.append(tid)
            bit_at.append(bit)
            rem.append(l - off)

        seq.append(-tid - 1)
        tid_at.append(-1)
        bit_at.append(0)
        rem.append(0)

    sa = _build_sa(seq)
    lcp = _build_lcp(seq, sa)

    m = len(seq)
    last = m - 1

    def exists(length: int) -> bool:
        mask = 0
        sa_l = sa
        lcp_l = lcp
        rem_l = rem
        bit_l = bit_at
        pop_l = pop
        kk = k

        for i in range(last):
            p = sa_l[i]
            if rem_l[p] >= length:
                mask |= bit_l[p]

            if lcp_l[i] < length:
                if pop_l[mask] >= kk:
                    return True
                mask = 0

        p = sa_l[last]
        if rem_l[p] >= length:
            mask |= bit_l[p]

        return pop_l[mask] >= kk

    # Binary search the maximum feasible length.
    lo = 0
    hi = max_len
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if exists(mid):
            lo = mid
        else:
            hi = mid - 1

    length = lo
    if length == 0:
        return (0, [])

    # Scan suffix array left-to-right to get the lexicographically smallest qualifying run.
    mask = 0
    first = -1
    sa_l = sa
    lcp_l = lcp
    rem_l = rem
    bit_l = bit_at
    pop_l = pop

    for i in range(last):
        p = sa_l[i]
        if rem_l[p] >= length:
            if first < 0:
                first = p
            mask |= bit_l[p]

        if lcp_l[i] < length:
            if first >= 0 and pop_l[mask] >= k:
                tid = tid_at[first]
                start = first - starts[tid]
                return (length, traces[tid][start:start + length])

            mask = 0
            first = -1

    p = sa_l[last]
    if rem_l[p] >= length:
        if first < 0:
            first = p
        mask |= bit_l[p]

    if first >= 0 and pop_l[mask] >= k:
        tid = tid_at[first]
        start = first - starts[tid]
        return (length, traces[tid][start:start + length])

    return (0, [])
